// Get the extracted intent parameters from the previous node
const intentData = $input.first().json.output;
const searchResults = $input.all();

// Filter out the first item which contains the intent data
const events = searchResults.slice(1).map(item => item.json);

// Initialize match results
let matchedEvents = [];
let matchStatus = 'no_match';

// If we have events to search through
if (events.length > 0) {
  // Filter by title if provided
  if (intentData.event_title) {
    const titleLower = intentData.event_title.toLowerCase();
    matchedEvents = events.filter(event => {
      const eventTitle = (event.summary || '').toLowerCase();
      return eventTitle.includes(titleLower);
    });
  } else {
    matchedEvents = events;
  }

  // Further filter by participants if provided
  if (intentData.participants && intentData.participants.length > 0) {
    matchedEvents = matchedEvents.filter(event => {
      if (!event.attendees || event.attendees.length === 0) return false;

      const eventEmails = event.attendees.map(a => a.email.toLowerCase());
      return intentData.participants.some(participant => 
        eventEmails.some(email => email.includes(participant.toLowerCase()))
      );
    });
  }

  // Determine match status
  if (matchedEvents.length === 0) {
    matchStatus = 'no_match';
  } else if (matchedEvents.length === 1) {
    matchStatus = 'single_match';
  } else {
    matchStatus = 'multiple_matches';
  }
}

// Return the results
return {
  json: {
    match_status: matchStatus,
    match_count: matchedEvents.length,
    matched_events: matchedEvents,
    intent_data: intentData
  }
};

